#ifndef B43FW_H_
#define B43FW_H_

/*
 * Firmware built into the program (b43fw.c, generated by Tools/fw2c.py),
 * for development builds only: a program built with it contains the
 * Broadcom firmware and cannot be published. Release builds have none
 * (fw2c.py --none) and read the firmware from files (b43fwfile.h).
 */
#include "b43os9.h"

/* The default firmware: the four files in firmware/. 0 = fw filled,
 * -1 = no firmware built in. */
int b43_builtin_firmware(b43os9_firmware *fw);

/* Other versions built in, from firmware/fw-<version>/, to compare firmware
 * versions on the Mac without rebuilding.
 *   name   0 = the version of the default firmware ("default" if unknown),
 *          1.. = the other versions, NULL after the last one (NULL for 0
 *          too when no firmware is built in);
 *   named  0 = fw filled with that version, -1 = not built in. */
const char *b43_builtin_firmware_name(int idx);
int b43_builtin_firmware_named(const char *name, b43os9_firmware *fw);

#endif /* B43FW_H_ */
